  for (i4 = 0; i4 < lvArr.length; i4++) { var v4 = lvArr[i4]; if (v4 > 0) { if (v4 < pMin) pMin = v4; if (v4 > pMax) pMax = v4; } }
  var padP = (pMax - pMin) * 0.08 || 1; pMin -= padP; pMax += padP;
