  var vMax = 0; for (i4 = i0; i4 < END; i4++) if (V[i4] > vMax) vMax = V[i4];
  if (!vMax) vMax = 1;
  var vTop = PADT + Hp + GAP, yV = function (v) { return vTop + Hv - (v / vMax) * Hv; };
  var sTop = vTop + Hv + GAP, yS = function (v) { return sTop + Hs - (v / 100) * Hs; };
  var totalH = sTop + Hs + 26;
